cfg_io_driver ! { #[doc = " Associates an I/O resource with the reactor instance that drives it."] #[doc = ""] #[doc = " A registration represents an I/O resource registered with a Reactor such"] #[doc = " that it will receive task notifications on readiness. This is the lowest"] #[doc = " level API for integrating with a reactor."] #[doc = ""] #[doc = " The association between an I/O resource is made by calling"] #[doc = " [`new_with_interest_and_handle`]."] #[doc = " Once the association is established, it remains established until the"] #[doc = " registration instance is dropped."] #[doc = ""] #[doc = " A registration instance represents two separate readiness streams. One"] #[doc = " for the read readiness and one for write readiness. These streams are"] #[doc = " independent and can be consumed from separate tasks."] #[doc = ""] #[doc = " **Note**: while `Registration` is `Sync`, the caller must ensure that"] #[doc = " there are at most two tasks that use a registration instance"] #[doc = " concurrently. One task for [`poll_read_ready`] and one task for"] #[doc = " [`poll_write_ready`]. While violating this requirement is \"safe\" from a"] #[doc = " Rust memory safety point of view, it will result in unexpected behavior"] #[doc = " in the form of lost notifications and tasks hanging."] #[doc = ""] #[doc = " ## Platform-specific events"] #[doc = ""] #[doc = " `Registration` also allows receiving platform-specific `mio::Ready`"] #[doc = " events. These events are included as part of the read readiness event"] #[doc = " stream. The write readiness event stream is only for `Ready::writable()`"] #[doc = " events."] #[doc = ""] #[doc = " [`new_with_interest_and_handle`]: method@Self::new_with_interest_and_handle"] #[doc = " [`poll_read_ready`]: method@Self::poll_read_ready`"] #[doc = " [`poll_write_ready`]: method@Self::poll_write_ready`"] #[derive (Debug)] pub (crate) struct Registration { #[doc = " Handle to the associated runtime."] #[doc = ""] #[doc = " TODO: this can probably be moved into `ScheduledIo`."] handle : scheduler :: Handle , #[doc = " Reference to state stored by the driver."] shared : Arc < ScheduledIo >,}
}